65	    // A parsed pairing request awaiting the user's confirmation because it would
66	    // REPLACE an existing pairing (a silent re-pair from a hostile QR/deep-link
67	    // would otherwise redirect all keystrokes to an attacker's host).
68	    @Published var pendingPairing: PairingCredentials?
