70	    func handlePairingURL(_ url: URL) {
71	        guard url.scheme == "cmux-bridge",
72	              url.host == "pair",
73	              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
74	              let host = components.queryItems?.first(where: { $0.name == "host" })?.value,
75	              let portStr = components.queryItems?.first(where: { $0.name == "port" })?.value,
76	              let port = Int(portStr),
77	              let token = components.queryItems?.first(where: { $0.name == "token" })?.value
78	        else { return }
79	
80	        let tailscaleHost = components.queryItems?.first(where: { $0.name == "tailscale_host" })?.value
81	        let credentials = PairingCredentials(host: host, port: port, token: token, tailscaleHost: tailscaleHost)
82	
83	        // First-time pairing (or re-pairing the exact same host) is committed
84	        // immediately. Any change to an existing pairing requires confirmation.
85	        if let existing = try? pairingStore.load(),
86	           existing.host != host || existing.port != port || existing.token != token {
87	            pendingPairing = credentials
88	            return
89	        }
90	        commitPairing(credentials)
91	    }
