230	    /// Reads a surface's text. cmux's `surface.read_text` returns the last
231	    /// `lines` rows *including terminal scrollback* — so a large `lines` value
232	    /// yields the scrollable history directly, with no separate load step. The
233	    /// focused surface asks for a deep window (history); background surfaces a
234	    /// shallow one (cheap live preview). Note: full-screen TUIs like claude-code
235	    /// repaint a fixed viewport and keep little/no terminal scrollback, so for
236	    /// those this returns roughly the visible screen — that's a cmux limitation,
237	    /// not a bug here. See [[project_cmux_no_scrollback]].
238	    func readSurfaceText(_ surfaceID: String, lines: Int = 50) {
239	        var params: [String: Any] = ["surface_id": surfaceID, "lines": lines]
240	        if let wsID = currentWorkspaceID {
241	            params["workspace_id"] = wsID
242	        }
243	        send(method: "surface.read_text", params: params) { [weak self] result in
244	            guard let self, let text = result["text"] as? String else { return }
245	            let content = Self.capHistoryLines(Self.trimTerminalText(text))
246	            // Diff before assigning: a no-op write to a @Published dictionary
247	            // still fires objectWillChange every poll.
248	            if self.surfaceContent[surfaceID] != content {
249	                self.surfaceContent[surfaceID] = content
250	            }
251	        }
252	    }
