254	    /// How many rows to request for the focused surface — deep enough to scroll
255	    /// back through, bounded so a huge scrollback can't produce a payload that
256	    /// stalls the socket or an attributed string UITextView can't lay out.
257	    static let focusedHistoryLines = 1500
258	
259	    /// Loads a claude surface's conversation history from its session transcript
260	    /// (via the bridge's `claude.transcript`) into `claudeTranscript`, for the
261	    /// full-screen history viewer. Claude runs as a full-screen TUI whose
262	    /// terminal exposes no scrollback, so the transcript is the real history.
263	    func loadClaudeTranscript(_ surfaceID: String) {
264	        guard !claudeTranscriptLoading.contains(surfaceID) else { return }
265	        claudeTranscriptLoading.insert(surfaceID)
266	        var params: [String: Any] = ["surface_id": surfaceID, "max_messages": 300]
267	        if let wsID = currentWorkspaceID {
268	            params["workspace_id"] = wsID
269	        }
270	        // Safety net: BridgeClient drops pending completions on disconnect
271	        // without calling them, so clear the loading flag on a timeout too —
272	        // otherwise the viewer's spinner would hang forever. Both paths do an
273	        // idempotent remove, so the race is harmless.
274	        DispatchQueue.main.asyncAfter(deadline: .now() + 15) { [weak self] in
275	            self?.claudeTranscriptLoading.remove(surfaceID)
276	        }
277	        send(method: "claude.transcript", params: params) { [weak self] result in
278	            guard let self else { return }
279	            self.claudeTranscriptLoading.remove(surfaceID)
280	            let text = (result["text"] as? String).map(Self.trimTerminalText) ?? ""
281	            let sessionID = result["session_id"] as? String ?? ""
282	            // Diagnostic: the surface we asked for vs the session the bridge
283	            // resolved it to. If these ever look mismatched, this line names the
284	            // exact ids to chase (the bridge maps surface → resume_binding →
285	            // <checkpoint_id>.jsonl and echoes the resolved session_id back).
286	            print("[Transcript] surface=\(surfaceID) -> session=\(sessionID) (\(text.count) chars)")
287	            self.claudeTranscriptSession[surfaceID] = sessionID
288	            self.claudeTranscript[surfaceID] = text
289	        }
290	    }
