292	    /// Trim trailing whitespace per line and remove blank trailing lines.
293	    nonisolated private static func trimTerminalText(_ text: String) -> String {
294	        text
295	            .split(separator: "\n", omittingEmptySubsequences: false)
296	            .map { $0.replacingOccurrences(of: "\\s+$", with: "", options: .regularExpression) }
297	            .joined(separator: "\n")
298	            .replacingOccurrences(of: "\\n+$", with: "", options: .regularExpression)
299	    }
