305	    nonisolated private static func capHistoryLines(_ text: String) -> String {
306	        let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
307	        guard lines.count > maxHistoryLines else { return text }
308	        return lines.suffix(maxHistoryLines).joined(separator: "\n")
309	    }
