370	    func refreshWorkspaces(then completion: (() -> Void)? = nil) {
371	        // Both list + current must land before firing `completion`, otherwise
372	        // follow-up work (refreshSurfaces) can run against an empty workspace
373	        // list or an unset current ID depending on which reply arrives first.
374	        // Both callbacks run on the main actor, so `pending` needs no locking.
375	        var pending = 2
376	        let step = {
377	            pending -= 1
378	            if pending == 0 { completion?() }
379	        }
380	        send(method: "workspace.list", params: [:]) { [weak self] result in
381	            if let list = result["workspaces"] as? [[String: Any]] {
382	                self?.workspaces = list.compactMap(Workspace.init)
383	            }
384	            step()
385	        }
386	        send(method: "workspace.current", params: [:]) { [weak self] result in
387	            if let id = result["id"] as? String { self?.currentWorkspaceID = id }
388	            step()
389	        }
390	    }
