392	    func refreshSurfaces(workspaceID: String? = nil) {
393	        var params: [String: Any] = [:]
394	        if let id = workspaceID ?? currentWorkspaceID {
395	            params["workspace_id"] = id
396	        }
397	        send(method: "surface.list", params: params) { [weak self] result in
398	            if let list = result["surfaces"] as? [[String: Any]] {
399	                self?.surfaces = list.compactMap(Surface.init)
400	                // Validate remembered surface still exists
401	                if let localID = self?.localFocusedSurfaceID,
402	                   self?.surfaces.contains(where: { $0.id == localID }) == false {
403	                    self?.localFocusedSurfaceID = nil
404	                }
405	                // Auto-select first surface if nothing is focused
406	                if self?.focusedSurfaceID == nil, let first = self?.surfaces.first {
407	                    self?.localFocusedSurfaceID = first.id
408	                }
409	            }
410	        }
411	    }
