506	    func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage) {
507	        switch message {
508	        case .connected(let payload):
509	            connectionStatus = .connected(cmuxConnected: payload.cmuxConnected)
510	        case .notificationCreated(let n):
511	            notifications.insert(n, at: 0)
512	            print("[Notification] id=\(n.id) surfaceID=\(n.surfaceID ?? "nil") workspaceID=\(n.workspaceID ?? "nil") title=\(n.title)")
513	            print("[Notification] surface IDs: \(surfaces.map(\.id))")
514	            scheduleLocalNotification(n)
515	        case .notificationCleared:
516	            notifications = []
517	        case .cmuxConnected:
518	            connectionStatus = .connected(cmuxConnected: true)
519	            refreshWorkspaces {
520	                self.refreshSurfaces()
521	                self.refreshPanes()
522	            }
523	        case .cmuxDisconnected:
524	            connectionStatus = .connected(cmuxConnected: false)
525	            panes = []
526	        case .commandResponse:
527	            break
528	        }
529	    }
530	}
